use serde :: { Deserialize , Serialize } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " A URL parameter specification with its name and optional preset options."] # [doc = ""] # [doc = " When `options` is `Some`, the UI presents a dropdown for selection."] # [doc = " When `options` is `None`, the UI presents a free-text input."] # [doc = " When `optional` is `true`, the parameter may be left blank and missing"] # [doc = " values are silently ignored during credential creation and URL rendering."] # [derive (Debug , Clone , PartialEq , Serialize , Deserialize)] pub struct URLParamSpec { # [doc = " The parameter name used as the template variable and credential map key."] pub name : URLParam , # [doc = " Optional list of allowed values. When present, the UI renders a"] # [doc = " dropdown."] pub options : Option < Vec < String > > , # [doc = " Whether this parameter is optional. When `true`, the parameter may be"] # [doc = " left blank without causing an error."] # [serde (default)] pub optional : bool , }